create table docs (id int primary key, body jsonb);
insert into docs values (1, '{"name":"x","tags":["a","b"],"n":1}'), (2, '{"name":"y","tags":["b"],"n":2,"extra":{"k":true}}'), (3, '{"name":"z","tags":[],"n":null}'), (4, null), (5, '[1,2]');
select id from docs where body @> '{"tags":["b"]}';
select id from docs where body ? 'extra';
select id, body ->> 'name', jsonb_array_length(body -> 'tags') from docs where jsonb_typeof(body) = 'object';
select id, body -> 'n' from docs where (body ->> 'n')::int > 1;
select t, count(*) from docs, jsonb_array_elements_text(body -> 'tags') t group by t;
update docs set body = jsonb_set(body, '{n}', to_jsonb(coalesce((body ->> 'n')::int, 0) + 10)) where jsonb_typeof(body) = 'object' returning id, body;
update docs set body = body || '{"seen":true}' where id < 3 returning body;
update docs set body = body - 'tags' where id = 1 returning body;
select id, body from docs order by id;
select sum((body ->> 'n')::int), jsonb_agg(body -> 'name' order by id) from docs where jsonb_typeof(body) = 'object';
select jsonb_array_length(body) from docs where id = 3;
select body -> 'name' -> 'x', body #>> '{extra,k}' from docs where id = 2;
